def table(f):
 keys=['candidate','pds','fidelity','reach','jaccard','nmae','common_expression_ratio','shape_wasserstein'];f=f.reset_index();lines=['| '+' | '.join(keys)+' |','|'+'|'.join(['---']*len(keys))+'|']
 for _,r in f.iterrows():lines.append('| '+' | '.join(str(r[k]) if k=='candidate' else (f'{r[k]:.8g}' if pd.notna(r[k]) else 'unavailable') for k in keys)+' |')
 return '\n'.join(lines)

def main():
 select=json.loads((A/'selection.json').read_text());confirm=json.loads((A/'confirmation_result.json').read_text());dev=pd.read_csv(A/'development_summary.csv');res=pd.read_csv(A/'confirmation_summary.csv');audit=json.loads((A/'independent_experiment_audit.json').read_text());assert audit['passed'];passed=bool(confirm['new_candidate_passes']);chosen=select['candidate'];released=(A/'submission_ready.json').exists() and (A/'independent_validation.json').exists();status='Passed the locked raw-condition reserve' if passed else 'Rejected by the locked raw-condition reserve';ready={}
 if released:
  ready=json.loads((A/'submission_ready.json').read_text());validation=json.loads((A/'independent_validation.json').read_text());assert passed and validation['passed'] and validation['package_sha256']==ready['sha256'] and ready['sha256']==b.sha256(OUT/'prediction.vcc');ready.update(upload_ready=True,independent_validation_sha256=b.sha256(A/'independent_validation.json'));b.write_json(A/'submission_ready.json',ready)
 lines=['# V24 measured results',f'\n**{status}.** Locked candidate: `{chosen}`. '+('The new package passed official preparation and independent full-payload validation.' if released else 'No upload-ready new package is claimed by this report.'),'\nV16 remains the best published project result, overall0.1416138568460195. V24 has not been uploaded and has no leaderboard score.','\n## Development\n','36 cases and eight arms =288 full-count populations. The28 previously studied family-holdout cases have400 cells; eight Rest D1 cases have200 cells and overlap public summaries, so they are training-like calibration. All Stim48hr responses are excluded from teacher and baseline fitting. HCT116 NMAE is unavailable. Baseline is the V16 mechanism refit without Stim48hr, not the exact published package.\n',table(dev),'\nThe development-only winner is selected by predeclared metric-improvement ranks. Three finalists pass available guards; the direction-only expert wins. Its raw changes relative to the same-input comparator are:\n']
 c=next(v for v in select['comparisons'] if v['candidate']==chosen)
 lines+=['```json',json.dumps(c['changes'],indent=2),'```','\n## Once-only fresh condition reserve\n','Eight metadata-selected targets,400 distinct real treated cells each,400 unique templates and disjoint lane-stratified reference controls. Same public study; condition response rows are withheld, but upstream nuisance preprocessing may overlap. No independent-study or hidden-anchor accuracy claim. All experimental arms are retained for diagnosis; only the locked development winner is assessed for release.\n',table(res),'\nLocked candidate checks and changes:\n','```json',json.dumps(confirm['comparisons'][0],indent=2),'```','\n## Independent checks\n','Two focused model tests pass (withheld-response removal, bounded correction, zero-compatibility identity and absent-evidence abstention). Source/code hashes, every frozen original cell identity, all count-profile cache hashes, condition exclusions and independent case/formula rechecks pass. The auditor replays both V16 and selected predictions in five full-axis cases (10 generated populations) and checks no-effect identity to the inherited emitter. This does not establish calibrated null DE.\n','```json',json.dumps(audit,indent=2),'```']
 if released:
  changes=pd.read_csv(A/'production_response_changes.csv');lines+=['\n## Production artifact\n',f'`experiments/v24_cd4_response/prediction.vcc`: {ready["bytes"]:,} bytes; SHA256 `{ready["sha256"]}`. All900 groups,360,000 cells and18,533 genes pass official requirements. '+f'{int((changes.changed_genes>0).sum())} groups receive new effects; unchanged groups reuse verified V16 count blocks. All three public conditions are used only in final refitting. Every production coefficient is independently reconstructed; every packaged CSR value/index/pointer is compared and12 full groups are regenerated exactly. Original control IDs, guides, unique sampling and libraries are checked for every prediction.','\nNo automatic upload or Git push occurred. See V24_SUBMISSION.md for the exact CMD upload command.']
 (ROOT/'V24_RESULTS.md').write_text('\n'.join(lines)+'\n',encoding='utf-8')
 submit=['# V24 submission status','',status+'.','', 'Frozen candidate: '+chosen+'. '+('Upload-ready, independently verified; not uploaded.' if released else 'No new validated upload package. Do not submit a rejected experiment.'),'']
 if released:
  submit +=[f'File: `experiments/v24_cd4_response/prediction.vcc` ({ready["bytes"]:,} bytes).',f'SHA256: `{ready["sha256"]}`.','','Windows Command Prompt:','','```bat','cd /d L:\\promec\\Animesh\\Download\\Virtual','.\\.competition_env\\Scripts\\python.exe -m vcc submit .\\experiments\\v24_cd4_response\\prediction.vcc -m "Context-matched donor response v24" --wait','```','','V16 remains the published champion until the host scores this file. Local tests do not guarantee a higher leaderboard result. If upload finishes and waiting is interrupted, use vcc status <entry-id> --wait instead of creating a duplicate submission.']
 else:submit +=['V16 remains the published champion. Its unchanged package is experiments/v16_control_preserving/prediction.vcc; uploading it again would not evaluate a new model.']
